type Vulnerability struct {
	ID           string    `json:"id"`
	Component    string    `json:"component"`
	Ranges       []Range   `json:"affected_ranges"`
	Severity     Severity  `json:"severity"`
	FixedVersion string    `json:"fixed_version"`
	Status       Status    `json:"status"`
