		if affected.Upper != nil {
			compare := lower.Compare(v.upperParsed[index])
			if compare > 0 || (compare == 0 && (!lowerInclude || !*affected.UpperInclude)) {
				continue
			}
		}
		matched = append(matched, affected)
	}
	return matched
}

