func isUniqueViolation(err error) bool {
	var sqliteErr *libsqlite.Error
	if errors.As(err, &sqliteErr) {
		// 19 is SQLITE_CONSTRAINT, 2067/2062 are UNIQUE/PK extended codes.
		code := sqliteErr.Code()
		if code == 19 || code == 2067 || code == 2062 {
			return true
		}
	}
	return false
}

