			{"lower": "3.2.1", "lower_include": true, "upper": "3.2.1", "upper_include": false},
		}),
		"range bad bound": withValue(validUpdateBody(), "affected_ranges", []map[string]any{
			{"lower": "3.x", "lower_include": true},
		}),
