func TestReplaceVulnerabilityOverwritesEverythingButID(t *testing.T) {
	st := openTestStore(t)
	ctx := context.Background()
	original := sampleVulnerability("CVE-2024-2000")
	if err := original.PrepareRanges(); err != nil {
